def rebuild_tensor(storage, offset, size, stride, requires_grad, hooks):
    arr = np.asarray(storage)
    n = 1
    for d in size:
        n *= d
    if n == 0:
        return np.zeros(tuple(size), dtype=arr.dtype)
    return arr[offset:offset+n].reshape(tuple(size))

def rebuild_parameter(t, requires_grad, hooks):
