        if module == '__main__':
            return Maze
        if module == 'torch._utils':
            return {'_rebuild_tensor_v2': rebuild_tensor, '_rebuild_parameter': rebuild_parameter}[name]
        if module == 'torch':
            return lambda *a: None
        if module == 'torch.nn.modules.linear':
            return Lin
        if module == 'collections':
            return collections.OrderedDict
